function validate([s, indices, sources, targets]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses lowercase English letters only.';
  if (!Array.isArray(indices) || !Array.isArray(sources) || !Array.isArray(targets)) return 'indices, sources and targets must be lists.';
  if (indices.length !== sources.length || indices.length !== targets.length) return 'indices, sources and targets need the same length.';
  if (indices.length < 1 || indices.length > 100) return 'There must be 1 to 100 operations.';
  const ranges = [];
  for (let k = 0; k < indices.length; k++) {
    if (!Number.isInteger(indices[k]) || indices[k] < 0 || indices[k] >= s.length) return 'Each index must point inside s.';
    for (const text of [sources[k], targets[k]]) {
      if (typeof text !== 'string' || text.length < 1 || text.length > 50) return 'Each source and target needs 1 to 50 characters.';
      if (!/^[a-z]+$/.test(text)) return 'Sources and targets use lowercase English letters only.';
    }
    if (s.startsWith(sources[k], indices[k])) ranges.push([indices[k], indices[k] + sources[k].length]);
  }
  ranges.sort((a, b) => a[0] - b[0]);
  for (let r = 1; r < ranges.length; r++) {
    if (ranges[r][0] < ranges[r - 1][1]) return 'Two matching replacements overlap.';
  }
  return null;
}

