function findReplaceString(s, indices, sources, targets) {
  const replaceAt = new Map();
  for (let k = 0; k < indices.length; k++) {
    const start = indices[k];
    if (s.startsWith(sources[k], start)) {
      replaceAt.set(start, k);
    }
  }
  const parts = [];
  let i = 0;
  while (i < s.length) {
    if (replaceAt.has(i)) {
      const k = replaceAt.get(i);
      parts.push(targets[k]);
      i += sources[k].length;
    } else {
      parts.push(s[i]);
      i++;
    }
  }
  return parts.join('');
}

