function findReplaceString(s, indices, sources, targets) {
  const matching = [];
  for (let k = 0; k < indices.length; k++) {
    const piece = s.slice(indices[k], indices[k] + sources[k].length);
    if (piece === sources[k]) matching.push(k);
  }
  // Apply from right to left so earlier positions stay valid.
  matching.sort((a, b) => indices[b] - indices[a]);
  let result = s;
  for (const k of matching) {
    result = result.slice(0, indices[k]) + targets[k] + result.slice(indices[k] + sources[k].length);
  }
  return result;
}

