function generate(rand, size) {
  const large = size === 'large';
  const pool = large ? 'abcd' : (rand() < 0.6 ? 'ab' : 'abc');
  const word = (len) => {
    let text = '';
    for (let i = 0; i < len; i++) text += pool[Math.floor(rand() * pool.length)];
    return text;
  };
  const n = large ? 1000 : 1 + Math.floor(rand() * 8);
  const s = word(n);
  const want = large ? 100 : 1 + Math.floor(rand() * 4);
  const covered = new Array(n).fill(false);
  const indices = [], sources = [], targets = [];
  for (let attempt = 0; attempt < 2000 && indices.length < want; attempt++) {
    const start = Math.floor(rand() * n);
    const maxLen = large ? (rand() < 0.1 ? 50 : 8) : 3;
    const len = 1 + Math.floor(rand() * maxLen);
    const source = rand() < 0.6 ? s.slice(start, start + len) : word(len);
    if (s.startsWith(source, start)) {
      let free = true;
      for (let j = start; j < start + source.length; j++) if (covered[j]) free = false;
      if (!free) continue;
      for (let j = start; j < start + source.length; j++) covered[j] = true;
    }
    indices.push(start);
    sources.push(source);
    targets.push(word(1 + Math.floor(rand() * (large ? 50 : 3))));
  }
  return [s, indices, sources, targets];
}
